<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\SchoolProfile; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class SchoolProfileController extends Controller { public function edit(){return view('admin.profile', ['profile'=>SchoolProfile::first()??new SchoolProfile]);} public function update(Request $r){$data=$r->validate(['name'=>'required|string|max:255','nsm'=>'nullable|string','npsn'=>'nullable|string','address'=>'nullable|string','phone'=>'nullable|string','whatsapp'=>'nullable|string','email'=>'nullable|email','website'=>'nullable|url','history'=>'nullable|string','vision'=>'nullable|string','mission'=>'nullable|string','headmaster_name'=>'nullable|string','headmaster_message'=>'nullable|string','logo'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048','favicon'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048','headmaster_photo'=>'nullable|image|mimes:jpg,jpeg,png,webp|max:2048']);$profile=SchoolProfile::first()??new SchoolProfile;foreach(['logo','favicon','headmaster_photo'] as $key)if($r->hasFile($key)){if($profile->$key)Storage::disk('public')->delete($profile->$key);$data[$key]=$r->file($key)->store('school','public');}$profile->fill($data)->save();return back()->with('success','Profil madrasah berhasil diperbarui.');} }
